(()=>{const c=window.siteConfig;document.querySelectorAll('[data-checkout]').forEach(a=>a.href=c.checkoutUrl);for(const [key,sel] of Object.entries({originalPrice:'[data-original-price]',installments:'[data-installments]',installmentValue:'[data-installment-value]',price:'[data-price]'}))document.querySelectorAll(sel).forEach(e=>e.textContent=c[key]);document.getElementById('year').textContent=new Date().getFullYear();const list=document.getElementById('faq-list');c.faq.forEach(([q,a],i)=>{const d=document.createElement('details');d.innerHTML=`<summary>${q}<span>+</span></summary><p>${a}</p>`;if(i===0)d.open=true;list.append(d)});document.querySelectorAll('.video').forEach(box=>box.querySelector('button')?.addEventListener('click',()=>{let id=box.dataset.video==='vsl'?c.vslUrl.split('/embed/')[1].split('?')[0]:box.dataset.video;box.innerHTML=`<iframe src="https://www.youtube-nocookie.com/embed/${id}?autoplay=1&rel=0&modestbranding=1" title="Vídeo Método Arcano" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen></iframe>`}));const sticky=document.querySelector('.sticky');addEventListener('scroll',()=>sticky.classList.toggle('show',scrollY>700),{passive:true});})();
